<input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="8" pattern="[0-9]{8}" placeholder="8-digit code" required value="<?= htmlspecialchars($code, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>">
<label for="user">Username</label>
<input id="user" name="username" autocomplete="username" placeholder="Your username" required>
<label for="pass">Password</label>
<div class="password-wrap"><input id="pass" name="password" type="password" autocomplete="current-password" placeholder="Your password" required><button class="show" id="show" type="button" aria-label="Show password">Show</button></div>
<button class="submit" id="submit" type="submit">Activate TV</button>
</form>
<p id="result" role="status" aria-live="polite"></p>
<p class="help">The TV code expires after 10 minutes.</p>
</main>
<footer>Flix Town · Movies &amp; Series</footer>
</div>
<script>
(() => {
 const endpoint='https://panelsandapps.com/panels/flixtown2027/api/pair-activate.php';
 const form=document.getElementById('form'),code=document.getElementById('code'),user=document.getElementById('user'),pass=document.getElementById('pass');
 const result=document.getElementById('result'),submit=document.getElementById('submit');
 code.addEventListener('input',()=>{code.value=code.value.replace(/\D/g,'').slice(0,8)});
 document.getElementById('show').addEventListener('click',e=>{const visible=pass.type==='text';pass.type=visible?'password':'text';e.currentTarget.textContent=visible?'Show':'Hide';e.currentTarget.setAttribute('aria-label',visible?'Show password':'Hide password')});
 function message(value,state){result.textContent=value;result.dataset.state=state}
 form.addEventListener('submit',async e=>{
  e.preventDefault();if(!form.reportValidity())return;submit.disabled=true;submit.textContent='Connecting…';result.removeAttribute('data-state');result.textContent='';
  try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:code.value,username:user.value,password:pass.value})});const data=await response.json();
   if(response.ok){pass.value='';message('Your TV is connected. Return to the app to start watching.','success')}
   else message(data.error||'Activation failed. Please try again.','error')
  }catch{message('Could not reach the activation service. Try again.','error')}
  finally{submit.disabled=false;submit.textContent='Activate TV'}
 });
})();
</script>
